export type Appearance = 'light' | 'dark';

type TokenGroup = Record<string, string>;
type SemanticMode = Record<string, TokenGroup>;

export interface TypeRole {
  size: number;
  lineHeight: number;
  weight: number;
}

interface ButtonRecipe {
  paddingX?: number;
